let evalReport=null,evalLoadError='',selectedEvalCase='no-pricing',evalDifferencesOnly=false,evalActiveStrategies=new Set(['fill','nulls','grounded']),candidateText='',candidateGrades=null;
const evalFieldLabels={business_name:'Business name',category:'Category',service_area:'Service area',email:'Email',starting_price:'Starting price',price_unit:'Price unit',services:'Services',delivery_timeline:'Delivery / planning'};
const evalRuleIds=['schema','accuracy','unknowns','evidence','uncertainty','followup'];
const evalRuleNames=['Profile schema','Supported facts preserved','Unknown values stay null','Exact supporting evidence','Ambiguity is flagged','Targeted follow-up'];
const beforeEvalsBind=bind,beforeEvalsRender=render;
const evalCase=()=>evalReport.cases.find(c=>c.id===selectedEvalCase);
const evalRows=()=>evalReport.records.filter(r=>r.caseId===selectedEvalCase&&evalActiveStrategies.has(r.strategy));
function evalValue(v,key){if(v===null||v===undefined)return 'Unknown';if(Array.isArray(v))return v.join(' · ');return key==='starting_price'&&typeof v==='number'?'$'+v.toLocaleString():String(v)}
function scoreBadge(row){const n=row.checks.filter(c=>c.pass).length;return `<span class="eval-verdict ${row.pass?'pass':'fail'}">${row.pass?'PASS':'FAIL'} · ${n}/6 checks</span>`}
function evalsScreen(){if(!evalReport)return heading('What happens when the call is incomplete?','Compare extraction outputs against the facts actually present in each transcript.')+`<section class="card"><h2>${evalLoadError?'Could not open the promptfoo report.':'Opening the promptfoo evaluation report…'}</h2><p>${esc(evalLoadError||'Loading the saved results and annotated transcript cases.')}</p><button class="secondary" id="retry-eval-report">Reload report</button></section>`;const chosen=evalCase(),rows=evalRows(),strategies=evalReport.strategies.filter(s=>evalActiveStrategies.has(s.id));return heading('A fuller profile isn’t always a better profile.','Compare what each output gets right, invents, or leaves for follow-up.',`<a class="secondary eval-download" href="evals/bubs-promptfoo-suite.zip" download>Download promptfoo suite ↓</a>`)+`<div class="eval-run-meta"><span><b>promptfoo ${esc(evalReport.version)}</b> · ${evalReport.cases.length} transcripts · 3 output strategies · 126 assertions</span><span>${esc(new Date(evalReport.timestamp).toLocaleString())}</span></div><div class="notice eval-scope"><span><b>Recorded fixture replay.</b> These hand-authored outputs illustrate three extraction strategies. The checks were run by promptfoo; no model was called. Scores describe these fixtures, not model performance. Eight core fields are a representative subset of the onboarding record.</span></div><div class="eval-summary">${evalReport.strategies.map(s=>{const rs=evalReport.records.filter(r=>r.strategy===s.id),all=rs.flatMap(r=>r.checks);return `<section class="card eval-summary-card"><span class="eyebrow">${s.id==='fill'?'01 · OVERCONFIDENT':s.id==='nulls'?'02 · CONSERVATIVE':'03 · SOURCE-GROUNDED'}</span><h2>${esc(s.label)}</h2><strong>${rs.filter(r=>r.pass).length}<small>/ 7 cases pass</small></strong><p>${all.filter(c=>c.pass).length} / 42 assertions pass</p><small>${esc(s.description)}</small></section>`}).join('')}</div><section class="card eval-matrix"><div class="card-head"><div><h2>Where does each strategy break?</h2><p>Select a transcript case to inspect its source, field differences, and assertion failures.</p></div><a href="evals/promptfoo-results.json" download>Raw promptfoo results ↓</a></div><div class="eval-table-scroll"><table class="table"><thead><tr><th>TRANSCRIPT CASE</th>${evalReport.strategies.map(s=>`<th>${esc(s.label)}</th>`).join('')}</tr></thead><tbody>${evalReport.cases.map(c=>`<tr class="${c.id===selectedEvalCase?'selected':''}"><td><button class="text-btn eval-case-button" data-eval-case="${c.id}">${esc(c.name)}</button><small>${esc(c.tag)}</small></td>${evalReport.strategies.map(s=>{const r=evalReport.records.find(r=>r.caseId===c.id&&r.strategy===s.id);return `<td><button class="eval-result-button" data-eval-case="${c.id}" aria-label="Inspect ${esc(c.name)} — ${esc(s.label)}">${scoreBadge(r)}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div></section><section class="card eval-source"><div class="card-head"><div><span class="eyebrow">SELECTED TEST CASE</span><h2 style="margin-top:10px">${esc(chosen.name)}</h2><p>${esc(chosen.description)}</p></div><select id="eval-case-select" aria-label="Transcript test case">${evalReport.cases.map(c=>`<option value="${c.id}" ${c.id===selectedEvalCase?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><pre class="eval-transcript">${esc(chosen.transcript)}</pre><details><summary>Inspect the annotated expected facts</summary><table class="table"><thead><tr><th>FIELD</th><th>EXPECTED VALUE</th><th>STATUS / SOURCE</th></tr></thead><tbody>${evalReport.keys.map(k=>{const e=chosen.expected[k];return `<tr><td>${evalFieldLabels[k]}</td><td>${esc(evalValue(e.value,k))}</td><td><b>${e.status}</b>${e.evidence?'<br>'+esc(e.evidence):'<br>No fact supplied in the transcript'}</td></tr>`}).join('')}</tbody></table></details></section><section class="card eval-comparison"><div class="card-head"><div><h2>Compare the vendor profiles</h2><p>Field values are shown alongside their stated certainty. Click a quote to compare it with the transcript.</p></div><label class="eval-toggle"><input type="checkbox" id="eval-differences" ${evalDifferencesOnly?'checked':''}> Differences only</label></div><div class="eval-strategy-controls">${evalReport.strategies.map(s=>`<label><input type="checkbox" data-eval-strategy="${s.id}" ${evalActiveStrategies.has(s.id)?'checked':''}> ${esc(s.label)}</label>`).join('')}</div><div class="eval-table-scroll"><table class="table eval-fields-table"><thead><tr><th>PROFILE FIELD</th>${strategies.map(s=>`<th>${esc(s.label)}</th>`).join('')}</tr></thead><tbody>${evalReport.keys.filter(k=>!evalDifferencesOnly||new Set(rows.map(r=>JSON.stringify(r.output.fields[k]))).size>1).map(k=>`<tr><td><b>${evalFieldLabels[k]}</b><small>Expected: ${esc(evalValue(chosen.expected[k].value,k))}</small></td>${rows.map(r=>{const f=r.output.fields[k],valid=JSON.stringify(f.value)===JSON.stringify(chosen.expected[k].value)&&f.status===chosen.expected[k].status;return `<td class="${valid?'':'eval-field-mismatch'}"><div class="eval-field-value">${esc(evalValue(f.value,k))}</div><span class="eval-status ${f.status}">${esc(f.status)}</span>${f.evidence?`<button class="text-btn eval-quote" data-eval-quote="${r.strategy}:${k}">View claimed evidence ↗</button>`:'<small>No source quote</small>'}${!valid?'<small class="eval-mismatch-label">Differs from expected fact / status</small>':''}</td>`}).join('')}</tr>`).join('')||`<tr><td colspan="${rows.length+1}">No differences in the selected outputs for this case.</td></tr>`}</tbody></table></div></section><div class="eval-checks-grid" style="--eval-columns:${strategies.length}">${rows.map(r=>`<section class="card eval-check-card"><h3>${esc(evalReport.strategies.find(s=>s.id===r.strategy).label)}</h3>${scoreBadge(r)}<ul class="eval-check-list">${r.checks.map(c=>`<li><details><summary><span class="${c.pass?'eval-check-pass':'eval-check-fail'}">${c.pass?'✓':'×'}</span> ${esc(c.name)}</summary><p>${esc(c.reason)}</p></details></li>`).join('')}</ul><h3 class="eval-followup-title">Follow-up questions</h3>${r.output.follow_up.length?`<ol class="eval-questions">${r.output.follow_up.map(q=>`<li><small>${evalFieldLabels[q.field]}</small>${esc(q.question)}</li>`).join('')}</ol>`:'<p class="eval-no-followup">No follow-up questions proposed.</p>'}<details class="eval-json"><summary>Inspect full profile JSON</summary><pre>${esc(JSON.stringify(r.output,null,2))}</pre><button class="text-btn" data-eval-download="${r.strategy}">Download this profile ↓</button></details></section>`).join('')}</div><section class="card eval-candidate"><div class="card-head"><div><h2>Check a different profile output</h2><p>Paste profile JSON for the selected transcript. This browser check uses the same six assertion functions; it does not start a new promptfoo run.</p></div></div><label for="eval-candidate-json">Candidate JSON · fields + follow_up schema</label><textarea id="eval-candidate-json" placeholder='{"fields": {…}, "follow_up": […]}'>${esc(candidateText)}</textarea><div class="eval-candidate-actions"><button class="secondary" id="eval-load-reference">Load reference JSON</button><button class="primary" id="eval-check-candidate">Check candidate locally →</button></div>${candidateGrades?`<div class="eval-candidate-results"><b>Local browser check: ${candidateGrades.filter(c=>c.pass).length} / 6 assertions pass</b>${candidateGrades.map(c=>`<details><summary>${c.pass?'✓':'×'} ${c.name}</summary><p>${esc(c.reason)}</p></details>`).join('')}</div>`:''}</section><section class="eval-method"><h3>How this evaluation is scored</h3><p>Each assertion is pass/fail; all six must pass for a case to pass. Exact quotes and normalized field values are checked against inspectable, human-authored annotations. Equivalent paraphrases can fail this deliberately strict suite. Coverage is illustrative, not comprehensive.</p><p>To compare real prompts or models, replace the fixture provider in the downloadable suite with your extraction implementation and rerun <code>npm run eval</code>. <a href="https://www.promptfoo.dev/docs/providers/custom-api/" target="_blank" rel="noopener">Promptfoo provider documentation ↗</a></p><small>Saved evaluation: ${esc(evalReport.evalId)} · The report reload button retrieves this saved run; it does not generate new outputs.</small><button class="text-btn" id="retry-eval-report">Reload saved report</button></section>`}
function evalDownload(value,filename){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}
async function loadEvalReport(){try{const response=await fetch('evals/report.json');if(!response.ok)throw Error('Saved report is unavailable.');const data=await response.json();if(data.records.length!==21||data.records.some(r=>r.checks.length!==6))throw Error('The saved report is incomplete.');evalReport=data;evalLoadError='';if(state.page==='evals')render()}catch(e){evalLoadError=e.message;if(state.page==='evals')render()}}
render=function(){beforeEvalsRender();if(state.page==='evals')$('#crumb').textContent='Profile evals'};
bind=function(){beforeEvalsBind();if($('#retry-eval-report'))$('#retry-eval-report').onclick=loadEvalReport;if(state.page!=='evals'||!evalReport)return;function chooseCase(id){selectedEvalCase=id;candidateGrades=null;render()};document.querySelectorAll('[data-eval-case]').forEach(b=>b.onclick=()=>chooseCase(b.dataset.evalCase));$('#eval-case-select').onchange=e=>chooseCase(e.target.value);$('#eval-differences').onchange=e=>{evalDifferencesOnly=e.target.checked;render()};document.querySelectorAll('[data-eval-strategy]').forEach(input=>input.onchange=()=>{if(!input.checked&&evalActiveStrategies.size<=2){input.checked=true;toast('Keep at least two outputs selected for comparison.');return}input.checked?evalActiveStrategies.add(input.dataset.evalStrategy):evalActiveStrategies.delete(input.dataset.evalStrategy);render()});document.querySelectorAll('[data-eval-quote]').forEach(b=>b.onclick=()=>{const [strategy,key]=b.dataset.evalQuote.split(':'),c=evalCase(),row=evalReport.records.find(r=>r.caseId===c.id&&r.strategy===strategy),quote=row.output.fields[key].evidence,index=c.transcript.indexOf(quote);$('#source-title').textContent=`${evalFieldLabels[key]} · ${evalReport.strategies.find(s=>s.id===strategy).label}`;$('#source-copy').innerHTML=`<div class="current-value"><small>CLAIMED EVIDENCE</small><strong>${esc(quote)}</strong><p>${index<0?'This quote does not occur in the transcript.':quote===c.expected[key].evidence?'This quote matches the annotated supporting passage.':'The text occurs in the transcript, but does not match the annotated supporting evidence for this fact.'}</p></div><pre class="evidence-document">${index<0?esc(c.transcript):esc(c.transcript.slice(0,index))+'<mark>'+esc(quote)+'</mark>'+esc(c.transcript.slice(index+quote.length))}</pre>`;$('#source').showModal()});document.querySelectorAll('[data-eval-download]').forEach(b=>b.onclick=()=>evalDownload(evalReport.records.find(r=>r.caseId===selectedEvalCase&&r.strategy===b.dataset.evalDownload).output,`${selectedEvalCase}-${b.dataset.evalDownload}.json`));$('#eval-candidate-json').oninput=e=>{candidateText=e.target.value;candidateGrades=null};$('#eval-load-reference').onclick=()=>{candidateText=JSON.stringify(evalReport.records.find(r=>r.caseId===selectedEvalCase&&r.strategy==='grounded').output,null,2);candidateGrades=null;render()};$('#eval-check-candidate').onclick=()=>{if(!candidateText.trim()){toast('Paste candidate profile JSON or load the reference example.');return}candidateGrades=evalRuleIds.map((id,i)=>{try{return{id,name:evalRuleNames[i],...BubsProfileGrade(candidateText,evalCase(),evalReport.keys,id)}}catch{return{id,name:evalRuleNames[i],pass:false,score:0,reason:'Invalid profile structure. Inspect the reference JSON for the expected schema.'}}});render()};};
if(location.hash==='#evals'){state.page='evals';transcriptOrigin=false;}loadEvalReport();render();
